// Presentation geometry: threshold positions use the same equal segments as the drawdown bar.
function v2DrawdownMarkerPercent(current,tiers) {
  const magnitude=Math.max(0,Math.min(100,Number(current)||0));
  const boundaries=[0,...tiers.map(t=>Number(t.drawdownThreshold))];
  let segment=0;boundaries.forEach((threshold,i)=>{if(magnitude>=threshold)segment=i;});
  const lower=boundaries[segment],upper=boundaries[segment+1]??100;
  const fraction=upper>lower?Math.min(1,(magnitude-lower)/(upper-lower)):0;
  return (segment+fraction)/boundaries.length*100;
}

