// Presentation geometry: equal strategy intervals with continuous interpolation.
function v2DrawdownMarkerPercent(current,tiers) {
  const magnitude=Math.max(0,Number(current)||0);
  const thresholds=tiers.map(t=>Number(t.drawdownThreshold)).filter(t=>Number.isFinite(t)&&t>0);
  if(!thresholds.length)return 0;
  let previous=0;
  for(let index=0;index<thresholds.length;index++){
    const threshold=thresholds[index];
    if(magnitude<=threshold)return (index+(magnitude-previous)/(threshold-previous))/thresholds.length*100;
    previous=threshold;
  }
  return 100;
}
